a<-commandArgs(TRUE);if(length(a)<3)stop("Usage: train_xgboost.R <dev> <val> <out> [vars] [seed]");if(!requireNamespace("xgboost",quietly=TRUE))stop("Install xgboost");tr<-read.csv(a[1],check.names=FALSE);va<-read.csv(a[2],check.names=FALSE);out<-a[3];v<-if(length(a)>=4)strsplit(a[4],",",TRUE)[[1]]else setdiff(names(tr),c("Time","Event"));seed<-if(length(a)>=5)as.integer(a[5])else 123L;dir.create(out,recursive=TRUE,showWarnings=FALSE);set.seed(seed);inner<-sample(seq_len(nrow(tr)),floor(.8*nrow(tr)));lab<-ifelse(tr$Event==1,tr$Time,-tr$Time);dm1<-xgboost::xgb.DMatrix(as.matrix(tr[inner,v,drop=FALSE]),label=lab[inner]);dm2<-xgboost::xgb.DMatrix(as.matrix(tr[-inner,v,drop=FALSE]),label=lab[-inner]);par<-list(objective="survival:cox",eval_metric="cox-nloglik",eta=.03,max_depth=3,subsample=1,colsample_bytree=1,gamma=.5,seed=seed);fit<-xgboost::xgb.train(par,dm1,nrounds=2000,watchlist=list(train=dm1,inner_validation=dm2),early_stopping_rounds=50,verbose=0);score<-function(d)as.numeric(predict(fit,as.matrix(d[,v,drop=FALSE])));write.csv(data.frame(Time=tr$Time,Event=tr$Event,xgboost=score(tr)),file.path(out,"development_xgboost_predictions.csv"),row.names=FALSE);write.csv(data.frame(Time=va$Time,Event=va$Event,xgboost=score(va)),file.path(out,"validation_xgboost_predictions.csv"),row.names=FALSE);saveRDS(list(model=fit,predictors=v,inner_index=inner),file.path(out,"xgboost_model.rds"))
